CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE counters (spec_id TEXT NOT NULL, kind TEXT NOT NULL, high_water TEXT NOT NULL CHECK (high_water NOT GLOB '*[^0-9]*' AND (high_water = '0' OR high_water GLOB '[1-9]*')), PRIMARY KEY (spec_id, kind)) WITHOUT ROWID;
CREATE TABLE operations (operation_id TEXT PRIMARY KEY, method TEXT NOT NULL, spec_id TEXT NOT NULL, digest TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE reservations (operation_id TEXT PRIMARY KEY REFERENCES operations(operation_id), spec_id TEXT NOT NULL, kind TEXT NOT NULL, first_ordinal TEXT NOT NULL CHECK (first_ordinal NOT GLOB '*[^0-9]*' AND (first_ordinal = '0' OR first_ordinal GLOB '[1-9]*') AND first_ordinal != '0'), first_length INTEGER NOT NULL, last_ordinal TEXT NOT NULL CHECK (last_ordinal NOT GLOB '*[^0-9]*' AND (last_ordinal = '0' OR last_ordinal GLOB '[1-9]*')), count TEXT NOT NULL CHECK (count NOT GLOB '*[^0-9]*' AND (count = '0' OR count GLOB '[1-9]*') AND count != '0')) WITHOUT ROWID;
CREATE UNIQUE INDEX reservation_ranges ON reservations (spec_id, kind, first_length, first_ordinal);
CREATE INDEX reservation_maxima ON reservations (spec_id, kind, length(last_ordinal), last_ordinal);
CREATE TABLE entities (spec_id TEXT NOT NULL, element_id TEXT NOT NULL, kind TEXT NOT NULL, subject TEXT NOT NULL, ordinal TEXT CHECK (ordinal IS NULL OR (ordinal NOT GLOB '*[^0-9]*' AND (ordinal = '0' OR ordinal GLOB '[1-9]*') AND ordinal != '0')), PRIMARY KEY (spec_id, element_id)) WITHOUT ROWID;
CREATE UNIQUE INDEX entity_ordinals ON entities (spec_id, kind, ordinal);
CREATE INDEX entity_maxima ON entities (spec_id, kind, length(ordinal), ordinal) WHERE ordinal IS NOT NULL;
CREATE TABLE revisions (spec_id TEXT NOT NULL, element_id TEXT NOT NULL, revision TEXT NOT NULL CHECK (revision NOT GLOB '*[^0-9]*' AND (revision = '0' OR revision GLOB '[1-9]*') AND revision != '0'), subject TEXT NOT NULL, content TEXT NOT NULL, content_sha256 TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','retired','superseded')), reason TEXT, operation_id TEXT NOT NULL REFERENCES operations(operation_id), PRIMARY KEY (spec_id, element_id, revision), FOREIGN KEY (spec_id, element_id) REFERENCES entities(spec_id, element_id)) WITHOUT ROWID;
CREATE INDEX revision_maxima ON revisions (spec_id, element_id, length(revision), revision);
CREATE TABLE lifecycle_heads (spec_id TEXT NOT NULL, element_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('imported','active','retired','superseded')), revision TEXT, CHECK ((status='imported' AND revision IS NULL) OR (status!='imported' AND revision IS NOT NULL)), PRIMARY KEY (spec_id, element_id), FOREIGN KEY (spec_id, element_id) REFERENCES entities(spec_id, element_id), FOREIGN KEY (spec_id, element_id, revision) REFERENCES revisions(spec_id, element_id, revision)) WITHOUT ROWID;
CREATE TABLE lifecycle_lineage (spec_id TEXT NOT NULL, predecessor_id TEXT NOT NULL, predecessor_revision TEXT NOT NULL, successor_id TEXT NOT NULL, successor_revision TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('replace','split','merge')), reason TEXT NOT NULL, operation_id TEXT NOT NULL REFERENCES operations(operation_id), PRIMARY KEY (spec_id, predecessor_id, successor_id), FOREIGN KEY (spec_id, predecessor_id, predecessor_revision) REFERENCES revisions(spec_id, element_id, revision), FOREIGN KEY (spec_id, successor_id, successor_revision) REFERENCES revisions(spec_id, element_id, revision)) WITHOUT ROWID;
CREATE INDEX lineage_successors ON lifecycle_lineage (spec_id, successor_id);
CREATE TABLE lifecycle_receipts (operation_id TEXT PRIMARY KEY REFERENCES operations(operation_id), receipt TEXT NOT NULL, receipt_sha256 TEXT NOT NULL) WITHOUT ROWID;
